<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_login();
$config=__DIR__.'/config/database.php';if(!is_file($config)){http_response_code(503);exit('Database configuration is not ready.');}require $config;
if(($_SESSION['role']??'')!=='owner'){http_response_code(403);exit('Owner access required.');}
$notice='';$error='';$bid=current_business_id();
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf((string)($_POST['csrf']??'')))$error='Session expired. Please try again.';
 else{$action=(string)($_POST['action']??'create');
  if($action==='toggle'){$id=(int)($_POST['business_id']??0);if($id===$bid)$error='You cannot deactivate the company you are currently logged into.';else{$q=$pdo->prepare('UPDATE businesses SET is_active=IF(is_active=1,0,1) WHERE id=?');$q->execute([$id]);$notice='Company status updated.';}}
  else{$business=trim((string)($_POST['business_name']??''));$code=strtolower(trim((string)($_POST['company_code']??'')));$address=trim((string)($_POST['address']??''));$phone=trim((string)($_POST['phone']??''));$pan=trim((string)($_POST['pan_vat']??''));$owner=trim((string)($_POST['owner_name']??''));$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$code=trim((string)preg_replace('/[^a-z0-9-]+/','-',$code),'-');
   if(!$business||!$code||!$owner||!$username||strlen($password)<8)$error='Complete all required fields. Password must be at least 8 characters.';
   else{$pdo->beginTransaction();try{$q=$pdo->prepare('INSERT INTO businesses(business_name,slug,address,phone,pan_vat) VALUES(?,?,?,?,?)');$q->execute([$business,$code,$address?:null,$phone?:null,$pan?:null]);$newBid=(int)$pdo->lastInsertId();$q=$pdo->prepare("INSERT INTO users(business_id,name,username,password_hash,role) VALUES(?,?,?,?, 'owner')");$q->execute([$newBid,$owner,$username,password_hash($password,PASSWORD_DEFAULT)]);$pdo->commit();$notice='New company and owner login created. Company Code: '.$code;}catch(Throwable $e){$pdo->rollBack();$error='Company could not be created. Check that the Company Code is unique.';}}
  }
 }
}
$companies=$pdo->query("SELECT b.*,u.name owner_name,u.username FROM businesses b LEFT JOIN users u ON u.business_id=b.id AND u.role='owner' ORDER BY b.id")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Company Admin • MeroKhata</title><link rel="stylesheet" href="assets/css/style.css"><style>.msg{padding:10px;border-radius:8px;margin-bottom:12px}.ok{background:#ecfdf3;color:#166534}.err{background:#fff0f0;color:#991b1b}.status{font-weight:700}.inactive{opacity:.6}.smallbtn{padding:6px 9px;border:1px solid #ccd3dd;border-radius:6px;background:#fff}.accountbar{font-size:12px;margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,.18)}.accountbar a{color:#fff}</style></head><body><aside class="sidebar"><div class="brand">MeroKhata</div><div class="subbrand">System Administration</div><div class="nav"><button onclick="location.href='index.php'">Business Dashboard</button><button class="active">Company Management</button></div><div class="accountbar"><?=htmlspecialchars($_SESSION['name']??'Owner')?> · Owner<br><a href="logout.php">Logout</a></div></aside><main class="main"><div class="topbar"><h1>Company Management</h1><div class="muted">Create and control MeroKhata company accounts</div></div><section class="panel active"><?php if($notice):?><div class="msg ok"><?=htmlspecialchars($notice)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=htmlspecialchars($error)?></div><?php endif;?><div class="box"><h3>Add New Company</h3><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="grid"><label>Company Name *<input name="business_name" required></label><label>Company Code *<input name="company_code" required placeholder="e.g. abcstationery"></label><label>Address<input name="address"></label><label>Phone<input name="phone"></label><label>PAN/VAT<input name="pan_vat"></label><label>Owner Name *<input name="owner_name" required></label><label>Owner Username *<input name="username" required></label><label>Owner Password *<input name="password" type="password" minlength="8" required></label></div><div class="actions"><button class="primary">Create Company & Owner Login</button></div></form></div><div class="box"><h3>Companies</h3><table><thead><tr><th>Company</th><th>Code</th><th>Owner</th><th>Username</th><th>Contact</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($companies as $c):?><tr class="<?=$c['is_active']?'':'inactive'?>"><td><?=htmlspecialchars($c['business_name'])?></td><td><b><?=htmlspecialchars($c['slug'])?></b></td><td><?=htmlspecialchars((string)$c['owner_name'])?></td><td><?=htmlspecialchars((string)$c['username'])?></td><td><?=htmlspecialchars(trim((string)$c['phone'].' '.(string)$c['address']))?></td><td class="status"><?=$c['is_active']?'Active':'Inactive'?></td><td><?php if((int)$c['id']!==$bid):?><form method="post" onsubmit="return confirm('Change this company status?');"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="business_id" value="<?=$c['id']?>"><button class="smallbtn"><?=$c['is_active']?'Make Inactive':'Activate'?></button></form><?php else:?><span class="muted">Current</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>